# pylint: disable=too-many-arguments


from __future__ import annotations

__doc__ = """Abstract coefficient backend interface used by ADAA implementations."""

from typing import Any
from abc import ABCMeta, abstractmethod

import numpy as np

from .aux import configured_zero_tol


ZERO_TOL = configured_zero_tol()


class CoeffBackend(metaclass=ABCMeta):
    """
    The coefficient based backend.

    This routine collection is implemented as a class, because for specific
    backend implementations, auxilliary variables, special libraries or
    initialization might be required.
    """

    def __init__(self, *_args, **_kwargs):
        if __debug__:
            # print(f"Backend '{self.__class__.__name__}': __init__()")
            pass

    def coeff_add(
        self, co_r: Any, co_a: Any, co_b: Any, size: int, dtype: str
    ) -> None:
        """Adds operands op_a and op_b, write result to op_r."""
        if co_r is None:
            raise ValueError("Result operand must not be None")
        return self.coeff_linop(
            co_r, None, co_a, None, co_b, size=size, dtype=dtype
        )

    def coeff_sub(
        self, co_r: Any, co_a: Any, co_b: Any, size: int, dtype: str
    ) -> None:
        """Adds operands op_a and op_b, write result to op_r."""
        if co_r is None:
            raise ValueError("Result operand must not be None")
        return self.coeff_linop(
            co_r,
            None,
            co_a,
            -1,
            co_b,
            size=size,
            dtype=dtype,
        )

    def coeff_smul(
        self, co_r: Any, co_a: Any, scal, size: int, dtype: str
    ) -> None:
        """Scalar-multiply co_a with scal, write result to co_r."""
        if co_r is None:
            raise ValueError("Result operand must not be None")
        if co_a is None:
            return self.coeff_to_zero(co_r, size=size, dtype=dtype)
        return self.coeff_linop(
            co_r, scal, co_a, None, None, size=size, dtype=dtype
        )

    def coeff_sdiv(
        self, co_r: Any, co_a: Any, scal, size: int, dtype: str
    ) -> None:
        """Scalar-multiply co_a with scal, write result to co_r."""
        if co_r is None:
            raise ValueError("Result operand must not be None")
        if abs(scal) < ZERO_TOL:
            raise ZeroDivisionError("Division by zero")
        if co_a is None:
            return self.coeff_to_zero(co_r, size=size, dtype=dtype)
        return self.coeff_linop(
            co_r, 1 / scal, co_a, None, None, size=size, dtype=dtype
        )

    def coeff_neg(self, co_r: Any, co_a: Any, size: int, dtype: str) -> None:
        """Scalar-multiply co_a with scal, write result to co_r."""
        if co_r is None:
            raise ValueError("Result operand must not be None")
        return self.coeff_smul(co_r, co_a, -1, size=size, dtype=dtype)

    def coeff_to_zero(self, coeff_like: Any, size: int, dtype: str):
        """Set the passed coefficient vector to zero."""
        if coeff_like is None:
            return
        if size is None:
            try:
                size = len(coeff_like)
            except TypeError as exc:
                raise ValueError(
                    "size must be provided for coefficient buffers without len()"
                ) from exc
        self.coeff_linop(
            coeff_like,
            None,
            None,
            None,
            None,
            size=size,
            dtype=dtype,
        )

    def coeff_copy_data(self, targ: Any, source: Any, size: int, dtype: str):
        """Copy the data from source to targ."""
        if targ is None:
            return
        if source is None:
            return self.coeff_to_zero(targ, size=size, dtype=dtype)
        if targ is source:
            return
        self.coeff_linop(
            targ, None, source, None, None, size=size, dtype=dtype
        )

    def coeff_free(self, reference, size: int, dtype: str):
        """free the memory at ref."""
        return None

    def coeff_allclose(
        self,
        coeff_a,
        coeff_b,
        atol: float,
        rtol: float,
        size: int,
        dtype: str,
    ) -> bool:
        """
        Perform an ``allclose`` check on two backend coefficient arrays.

        The default implementation converts both operands to NumPy and delegates
        to :func:`numpy.allclose`.
        """
        return np.allclose(
            self.coeff_to_numpy(coeff_a, size=size, dtype=dtype),
            self.coeff_to_numpy(coeff_b, size=size, dtype=dtype),
            atol=atol,
            rtol=rtol,
        )

    ###########################################################################
    #
    # ABSTRACT METHODS
    # ================
    #

    @abstractmethod
    def coeff_new_array(self, size: int, dtype: str) -> Any:
        """Create an empty coeff array."""

    @abstractmethod
    def coeff_from_numpy(
        self, coeff_like: Any, nparray: np.ndarray, size: int, dtype: str
    ) -> None:
        """Fill the coeffs from a numpy array."""

    @abstractmethod
    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str
    ) -> np.ndarray:
        """Export the coeffs as a numpy array."""

    @abstractmethod
    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any,
        *,
        size: int,
        dtype: str,
        inplace: bool = False,
    ):
        """
        Perform the backend's basic linear operation.

        The operation is interpreted as::

            r = a * x + b * y

        If ``inplace`` is true, the backend should instead perform::

            r += a * x + b * y

        Either scalar may be passed as ``None`` to request the backend's
        default interpretation, which is typically equivalent to a factor of
        one when the corresponding array operand is present. If an array
        operand is ``None``, its contribution is skipped entirely.
        """


###############################################################################
